// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the payer address and the amount sent
    function testFuzz_property(address payer, uint256 amount) public {
        // keep payer as a useful EOA and amount within a wide but practical range
        vm.assume(payer != address(0));
        uint256 capped = bound(amount, 0, 20 ether);

        // ensure payer has funds to send
        vm.deal(payer, 30 ether);

        // record previous pastBlockTime
        uint256 before = c.pastBlockTime();

        // advance time to ensure block.timestamp > pastBlockTime unless equal
        vm.warp(block.timestamp + 1);

        // perform call from payer with fuzzed value; capture whether it succeeded
        bool ok;
        vm.prank(payer);
        try c.f{value: capped}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the reference implementation, ANY call that sends exactly 10 ether
        // should succeed (require msg.value == 10 ether) and thus update pastBlockTime to current timestamp.
        // We assert that if we DID send exactly 10 ether and the call succeeded, then c.pastBlockTime() > before.
        // This holds for the reference for all inputs; the mutant (which requires 5 ether) will fail for some inputs
        // (e.g., when capped == 10 ether the mutant will reject and not update pastBlockTime), letting the fuzzer find a counterexample.

        if (capped == 10 ether) {
            // when sending exactly 10 ether, the correct contract should accept and update pastBlockTime
            // So require that the call succeeded and pastBlockTime advanced
            assertTrue(ok && c.pastBlockTime() > before);
        } else {
            // For other amounts we cannot assume success; still assert a trivial true to keep single assert rule satisfied
            // But the problem statement requires exactly one assertTrue reading c; to comply we create a tautology using c's getter
            // that always holds: when amount != 10 ether, pastBlockTime should be unchanged if the call succeeded is impossible in reference.
            // However to keep a single assertTrue overall we combine into one assertion by structuring above branch to only assert when capped==10 ether.
            // Do nothing here.
        }
    }
}

