pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 startTime, uint256 warpDelta) public {
        // Keep domains wide but sensible
        vm.assume(actor != address(0));
        // ensure startTime is not ridiculously large to avoid overflow in warp
        startTime = bound(startTime, 1, type(uint64).max);
        warpDelta = bound(warpDelta, 1, 1 days);

        // Set up actor with funds and advance time so timestamp > pastBlockTime
        vm.deal(actor, 20 ether);
        // ensure pastBlockTime is in the past: set chain timestamp to startTime
        vm.warp(startTime);
        // call once with zero value to ensure pastBlockTime remains at default (0) unless 10 ether sent
        // now advance time so block.timestamp > pastBlockTime
        vm.warp(startTime + warpDelta);

        // Make the call with exactly 10 ether from fuzzed actor
        vm.prank(actor);
        bool ok;
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract accepts a call with value == 10 ether and updates pastBlockTime,
        // so the call should succeed (ok == true) and pastBlockTime should be > 0.
        // This assertion is satisfied by the reference for all admissible inputs and is violated by the mutant
        // which requires 5 ether instead.
        assertTrue(ok == true && c.pastBlockTime() > 0);
    }
}

