    function setUp() public { c = new C(); }

    // fuzzed params: an arbitrary caller address and an arbitrary block timestamp delta
    function testFuzz_property(address caller, uint64 timeDelta) public {
        // keep caller as a non-zero address (EOA); fuzzer may supply zero which isn't useful
        vm.assume(caller != address(0));

        // bound timeDelta to a reasonable range so warp moves forward but stays within uint256
        uint64 delta = uint64(bound(timeDelta, 1, 1 days));

        // fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // record previous pastBlockTime
        uint prev = c.pastBlockTime();

        // advance time to ensure block.timestamp > prev
        vm.warp(block.timestamp + delta);

        // perform the call sending exactly 10 ether from the fuzzed caller
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: the reference contract accepts a call with exactly 10 ether
        // and updates pastBlockTime to a strictly larger value. Assert that the call succeeded
        // and pastBlockTime increased. This holds for the reference and will be violated by
        // the mutant (which requires 5 ether) for some inputs.
        assertTrue(ok && c.pastBlockTime() > prev);
    }
}

