pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: a caller address and a timestamp value. The fuzzer will supply them.
    // We must not hard-code amounts or addresses; we will use vm.deal and vm.prank.
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // bound timestamp to reasonable uint range that fits block.timestamp
        uint256 warped = bound(ts, 0, type(uint256).max - 1);

        // Give caller enough ETH to send 10 ether
        vm.deal(caller, 20 ether);

        // First call: set pastBlockTime to warped by warping time and calling fallback with 10 ether
        vm.warp(warped);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Record pastBlockTime after first call via the public getter
        uint256 first = c.pastBlockTime();

        // Second call: do NOT advance time (same timestamp). This is the distinguishing scenario
        vm.warp(warped);
        vm.prank(caller);
        c.f{value: 10 ether}();

        uint256 second = c.pastBlockTime();

        // General rule: in the reference contract, pastBlockTime strictly increases on each successful fallback call
        // with the required payment (since it requires block.timestamp > pastBlockTime). Therefore first < second must hold.
        // The mutant that uses >= will allow first == second and thus violate this assertion for some inputs.
        assertTrue(first < second);
    }
}

