pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an actor address and a timestamp; the fuzzer will search values
    function testFuzz_property(address caller, uint256 ts) public {
        // admissible domain: caller should be a nonzero address
        vm.assume(caller != address(0));
        // sender must have funds to send 10 ether
        vm.deal(caller, 100 ether);

        // Step 1: set block timestamp to ts and make an initial successful call
        vm.warp(ts);
        vm.startPrank(caller);
        // perform fallback call with exactly 10 ether
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1); // ensure reference contract accepts this initial call
        vm.stopPrank();

        // record pastBlockTime after first call via auto getter
        uint256 before = c.pastBlockTime();

        // Step 2: make a second call in the same block/time to reveal mutant behavior if any
        vm.warp(ts); // keep the same timestamp (equal timestamps)
        vm.startPrank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        // second call may or may not succeed depending on contract logic, but for the
        // reference C it must succeed and update the pastBlockTime to a strictly larger value
        vm.stopPrank();

        // record after value
        uint256 after = c.pastBlockTime();

        // General invariant: after a successful fallback sending exactly 10 ether,
        // pastBlockTime strictly increases. Here we assert it using the observed values.
        // For the reference contract this holds for all inputs; the mutant using >=
        // can leave pastBlockTime unchanged (after == before) when two calls occur at equal timestamp.
        assertTrue(after > before);
    }
}

