contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTs, address caller) public {
        // keep inputs wide but sensible
        vm.assume(caller != address(0));
        // ensure warpTs is within uint32-ish range to mimic realistic timestamps but allow wide fuzzing
        warpTs = bound(warpTs, 1, type(uint64).max);

        // set block timestamp to warpTs
        vm.warp(warpTs);
        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // first call: record old time and perform call sending exactly 10 ether
        uint256 before = c.pastBlockTime();
        vm.prank(caller);
        c.f{value: 10 ether}();
        uint256 afterFirst = c.pastBlockTime();

        // After a successful call sending exactly 10 ether, reference contract must set pastBlockTime > before
        // To create the scenario that distinguishes the mutant, perform a second call in the same block/time
        // (no warp or roll), so block.timestamp is unchanged
        vm.prank(caller);
        c.f{value: 10 ether}();
        uint256 afterSecond = c.pastBlockTime();

        // The universal property we assert: afterFirst > before and afterSecond > afterFirst
        // However, some networks may start with before == 0 and afterFirst == warpTs; still must be strictly increasing
        // Single assertion reading c that holds for the correct contract for all inputs, and fails for mutant for some inputs
        assertTrue(afterSecond > afterFirst);
    }
}

